import{_ as r,o as t,c as i,ai as e}from"./chunks/framework.C33Uq6m-.js";const c=JSON.parse('{"title":"AI 训练","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/ai-training.md","filePath":"zh/guide/ai-training.md"}'),o={name:"zh/guide/ai-training.md"};function n(l,a,s,h,d,g){return t(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="ai-训练" tabindex="-1">AI 训练 <a class="header-anchor" href="#ai-训练" aria-label="Permalink to &quot;AI 训练&quot;">​</a></h1><p>AI 训练页让你收集、整理并导出用于微调语言模型的训练数据对。</p><p><strong>侧边栏位置：</strong> AI 训练 <strong>路由：</strong> <code>/training</code></p><h2 id="什么是训练数据对" tabindex="-1">什么是训练数据对？ <a class="header-anchor" href="#什么是训练数据对" aria-label="Permalink to &quot;什么是训练数据对？&quot;">​</a></h2><p>一个训练数据对由一条<strong>用户提示词</strong>和一条<strong>模型回复</strong>组成。通过收集高质量的数据对，你可以构建出一份数据集，用来把模型微调成你想要的样子。</p><h2 id="数据对是怎么收集来的" tabindex="-1">数据对是怎么收集来的 <a class="header-anchor" href="#数据对是怎么收集来的" aria-label="Permalink to &quot;数据对是怎么收集来的&quot;">​</a></h2><p>训练数据对会从你与工具工坊中 <strong>Canvas AI</strong> 功能的交互中自动捕获。当 AI 生成工具代码、起草改进方案或给出分析时，每一次交互都会成为一个训练数据对，存储在 IndexedDB 中。</p><h2 id="整理数据" tabindex="-1">整理数据 <a class="header-anchor" href="#整理数据" aria-label="Permalink to &quot;整理数据&quot;">​</a></h2><p>主界面是一张表格，列出所有已收集的训练数据对。对每一对你都可以：</p><h3 id="接受或拒绝" tabindex="-1">接受或拒绝 <a class="header-anchor" href="#接受或拒绝" aria-label="Permalink to &quot;接受或拒绝&quot;">​</a></h3><ul><li><strong>接受</strong> —— 标记为高质量训练数据</li><li><strong>拒绝</strong> —— 标记为不适用（输出糟糕、幻觉等）</li></ul><h3 id="编辑回复" tabindex="-1">编辑回复 <a class="header-anchor" href="#编辑回复" aria-label="Permalink to &quot;编辑回复&quot;">​</a></h3><p>点击任意回复即可编辑。当模型的输出已经接近正确、只是需要修正时，这非常有用 —— 你不必从头再来就能得到正确答案。</p><h3 id="打标签" tabindex="-1">打标签 <a class="header-anchor" href="#打标签" aria-label="Permalink to &quot;打标签&quot;">​</a></h3><p>为数据对添加标签，按主题、质量等级或任意自定义类别进行组织。标签便于筛选和导出特定子集。</p><h3 id="批量操作" tabindex="-1">批量操作 <a class="header-anchor" href="#批量操作" aria-label="Permalink to &quot;批量操作&quot;">​</a></h3><p>选中多个数据对即可：</p><ul><li><strong>批量接受 / 拒绝</strong> —— 一次性设置多对的状态</li><li><strong>批量加标签</strong> —— 为所有选中项应用同一个标签</li><li><strong>删除</strong> —— 移除不需要的数据对</li></ul><h2 id="筛选" tabindex="-1">筛选 <a class="header-anchor" href="#筛选" aria-label="Permalink to &quot;筛选&quot;">​</a></h2><p>可以按以下条件筛选训练数据对列表：</p><ul><li><strong>状态</strong> —— 已接受、已拒绝或未审阅</li><li><strong>标签</strong> —— 只显示带特定标签的数据对</li><li><strong>搜索</strong> —— 在提示词和回复中做全文搜索</li></ul><h2 id="导出" tabindex="-1">导出 <a class="header-anchor" href="#导出" aria-label="Permalink to &quot;导出&quot;">​</a></h2><p>选中你想导出的数据对（或用筛选缩小范围），然后点击<strong>导出</strong>。导出的数据集可直接用于各类微调工具与框架。</p><h2 id="统计" tabindex="-1">统计 <a class="header-anchor" href="#统计" aria-label="Permalink to &quot;统计&quot;">​</a></h2><p>页面顶部显示汇总统计：</p><ul><li>已收集的数据对总数</li><li>已接受与已拒绝的数量</li><li>标签分布</li></ul><h2 id="小贴士" tabindex="-1">小贴士 <a class="header-anchor" href="#小贴士" aria-label="Permalink to &quot;小贴士&quot;">​</a></h2><ul><li><strong>质量重于数量</strong> —— 一份精心挑选的小数据集，微调效果好过一份嘈杂的大数据集。</li><li><strong>编辑，而不是丢弃</strong> —— 如果一条回复已经对了 80%，编辑它比重新生成更高效。</li><li><strong>有策略地使用标签</strong> —— 按能力打标签（例如「代码生成」「API 工具」「解释说明」），便于构建聚焦的训练子集。</li></ul>',28)])])}const p=r(o,[["render",n]]);export{c as __pageData,p as default};
